    comment.ir_type == "Comment"
    regex.match("(?i).*\\b(BUG|HACK|FIXME|LATER|LATER2|TODO|WORKAROUND|TEMPORARY|XXX|SECURITY_ISSUE|HARDcoded|SKIP_CHECK|INCOMPLETE)\\b.*", comment.content)
