find_inline_comment(attr) = comment {
    attr.ir_type == "Attribute"
    attr.code != ""
    comment_regex := "#.*"
    regex.match(comment_regex, attr.code)
    comment_content := regex.findall(comment_regex, attr.code)[_]
    comment := {"ir_type": "Comment", "content": comment_content, "line": attr.line}
}

